INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26193$nota-0103$m26193$, $m26194$Training and Racing with a Power Meter.pdf$m26194$, $m26195$299$m26195$, $m26196$The MMP Curve is a plot of all your bests—your best 39 seconds, your best 56 seconds, your best 1:38, your best 5:42, your best 1:15:32, and so on... It is worth noting the differences between the Mean Maximal Power Curve and the Power Duration Curve (PDC). The Power Duration Curve is simply the line that best fits your MMP curve, and is used to help derive many of the metrics we have already discussed: FRC, Pmax, Stamina, and modeled FTP.$m26196$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26197$nota-0103$m26197$, $m26198$Training and Racing with a Power Meter.pdf$m26198$, $m26199$300$m26199$, $m26200$It is important to review both when considering fitness changes, but ultimately, your real-world power data in the MMP curve offers the best glimpse of your fitness, strengths, and weaknesses.$m26200$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m26201$nota-0103$m26201$, $m26202$nota-0037$m26202$, $m26203$pre-requisito$m26203$, $m26204$a PDC (nota-0037, conceito introdutório, e correlatas de Pmax/FRC/mFTP nota-0077/0078/0079) é o modelo ajustado derivado da MMP Curve descrita aqui$m26204$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26205$nota-0104$m26205$, $m26206$Training and Racing with a Power Meter.pdf$m26206$, $m26207$302$m26207$, $m26208$note that at 1 minute 25 seconds, the slope dramatically changes, and the new slope continues until about 7:25, at which point it flattens out even more. It could be that this slope shows the athlete moving from the anaerobic capacity system into the VO2max system and then transitioning into the lactate threshold system around that 7:25 mark.$m26208$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26209$nota-0104$m26209$, $m26210$Training and Racing with a Power Meter.pdf$m26210$, $m26211$303$m26211$, $m26212$Does this mean that you cannot do, say, 350 watts for 1:24, but you can do this same wattage for 1:45? No—that would not make sense... Remember: This is a curve of the best watts you produced for every 2- to 3-second increment over a long period of time. It's highly possible that you did a hard hill interval for 1:45 at about 350 watts but then did not do any maximal efforts for 1:24. Therefore, it's possible that your chart could show a higher wattage for that longer time period.$m26212$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m26213$nota-0104$m26213$, $m26214$nota-0103$m26214$, $m26215$pre-requisito$m26215$, $m26216$aplica-se sobre a MMP Curve definida na nota-0103$m26216$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26217$nota-0105$m26217$, $m26218$Training and Racing with a Power Meter.pdf$m26218$, $m26219$304$m26219$, $m26220$at longer durations, your average power will tend to be lower than the maximum wattage you can produce, in part because of the time you spend not pedaling. Thus, beyond about 1 hour (or beyond the longest, generally flat time trial that you have done), Normalized Power will be a more accurate measure of your true ability. In Figure 11.10, the upper line shows mean maximal power, while the lower line is the mean maximal Normalized Power. At about 7:25, they switch places and the Normalized Power becomes the upper line.$m26220$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m26221$nota-0105$m26221$, $m26222$nota-0059$m26222$, $m26223$pre-requisito$m26223$, $m26224$usa a definição de NP (nota-0059) e compara sua trajetória contra a potência média bruta (MMP) ao longo da duração do esforço$m26224$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26225$nota-0107$m26225$, $m26226$Training and Racing with a Power Meter.pdf$m26226$, $m26227$318$m26227$, $m26228$It is important to note that the FRC, Pmax, and mFTP can have a 'teeter-totter' relationship. Remember that you are tracking all of the area under your Power Duration Curve, and if you test your 1 minute and 5 minute power after a rest week and raise the FRC portion of the curve without also testing your 20- or 60-minute FTP power, then you will raise the left side of the curve up and the right side (durations longer than 5 minutes) will appear to drop by comparison. This is the reason you might see a drop in your modeled FTP after a new best for your FRC. It's not likely that your FTP actually dropped; rather it's a result of how the PDC is affected by your MMP Curve.$m26228$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m26229$nota-0107$m26229$, $m26230$nota-0103$m26230$, $m26231$pre-requisito$m26231$, $m26232$explica um artefato de modelagem da PDC (nota-0103), que é ajustada sobre a MMP Curve$m26232$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m26233$nota-0107$m26233$, $m26234$nota-0082$m26234$, $m26235$complementa$m26235$, $m26236$afeta diretamente a leitura de FRC, Pmax e mFTP consolidados no Mapa Fenotípico (nota-0082) e nas notas do Cap.8$m26236$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26237$nota-0108$m26237$, $m26238$Training and Racing with a Power Meter.pdf$m26238$, $m26239$318$m26239$, $m26240$Interestingly, the TTE (time to exhaustion) can be a preceding indicator to an FTP improvement. A TTE that moves closer and closer to or even exceeds 1 hour can be an indicator that the rider's FTP may increase very soon. Once the FTP improves, the TTE resets back to a lower time frame until the athlete can prove that he can maintain that power for the full hour again.$m26240$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m26241$nota-0108$m26241$, $m26242$nota-0079$m26242$, $m26243$complementa$m26243$, $m26244$acrescenta um papel preditivo ao conceito de TTE já definido nas notas do Cap.8 (tempo até exaustão na FTP)$m26244$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26245$nota-0110$m26245$, $m26246$Training and Racing with a Power Meter.pdf$m26246$, $m26247$326$m26247$, $m26248$The better part of most triathlons should be completed in Quadrants III (low force, slow cadence) and IV (low force, fast cadence), which means low force on the pedals and adjusting your gearing to pedal either slower or faster.$m26248$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26249$nota-0110$m26249$, $m26250$Training and Racing with a Power Meter.pdf$m26250$, $m26251$329$m26251$, $m26252$the athlete spent over 41 percent of his race in Quadrant II, which represents high force and low cadence. From an energy conservation standpoint, this is the worst quadrant: Quadrant II requires a particularly large amount of muscle glycogen.$m26252$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m26253$nota-0110$m26253$, $m26254$Training and Racing with a Power Meter.pdf$m26254$, $m26255$332$m26255$, $m26256$a triathlete with a Variability Index of 1.04 to 1.07 on the bike leg has done an excellent job of pedaling smoothly for the entire ride and has correctly limited his or her surges$m26256$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m26257$nota-0110$m26257$, $m26258$nota-0067$m26258$, $m26259$pre-requisito$m26259$, $m26260$aplica o conceito de Quadrant Analysis (nota-0067) especificamente ao objetivo de conservar glicogênio muscular no bike leg do triathlon$m26260$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m26261$nota-0110$m26261$, $m26262$nota-0060$m26262$, $m26263$pre-requisito$m26263$, $m26264$usa o Variability Index (nota-0060) como métrica-alvo quantitativa de suavidade de pedalada$m26264$)
